//! The transition crossfade: the other term of the envelope that does not
//! come from the voice being measured.
//!
//! `audio_duck.rs` is the first — a clip on some other TRACK pushing this
//! one down — and this is the second: the clip on the same track that this
//! one OVERLAPS (format version 7, spec §7.2, spec §11's R5-2). Both are
//! facts about the neighbourhood rather than about the clip, both are read
//! by `audio.rs` as one multiplier at a breakpoint, and both are a module
//! of their own for that reason.
//!
//! Two halves, and they have to agree: the GAIN at an instant, and the
//! ticks the envelope has to be sampled at for that gain to survive
//! coalescing. Neither the sine law nor an eased progress is a straight
//! line, so a crossfade that contributed no breakpoints would be flattened
//! into a single ramp from 1 to 0 and the constant-power curve would be
//! exactly the equal-gain one it exists to avoid.
//!
//! The law is `cos(p·π/2)` going out and `sin(p·π/2)` coming in, over the
//! EASED progress `transition.rs` reports, and 1 wherever there is no
//! overlap or the transition's `audio` is false — so a project written
//! before version 7 is untouched, and mute, solo, ducking, volume and the
//! fades all keep their precedence, since this multiplies rather than
//! replacing anything.

use std::f64::consts::FRAC_PI_2;

use crate::audio::{Side, Stage, ACTION_SAMPLE, MAX_ACTION_SAMPLES};
use crate::model::{FadeShape, Project};
use crate::time::Ticks;
use crate::transition;

impl Project {
    /// The constant-power crossfade multiplier at `t` for one stage (format
    /// version 7, spec §11's R5-2): `cos(p·π/2)` going out, `sin(p·π/2)`
    /// coming in, and 1 wherever there is no overlap or the transition's
    /// `audio` is false. That is `audio_shape`'s default, `plus_3db`; another
    /// shape (format 29, AU-115) gives `gain(p)` coming in and `gain(1 − p)`
    /// going out.
    ///
    /// Constant power rather than equal gain because the two clips of a
    /// transition are UNCORRELATED material — a Remove Silences cut, a jump
    /// between takes — where `cos² + sin² = 1` holds the level and a linear
    /// pair dips 3 dB in the middle.
    ///
    /// It is measured in the CONTAINER's time base over the CONTAINER's
    /// clips, because an overlap is a fact about neighbours and a nested
    /// clip's neighbours are the nest's. `t - origin` is clip time and
    /// `+ clip.start` puts it back on the container's own clock —
    /// `recipe.rs`'s `local`, the same mapping.
    ///
    /// Every stage multiplies its own term, so a clip inside an overlap
    /// inside a nest that is ITSELF in a transition gets both fades. That
    /// differs from the picture, where `recipe.rs` picks the clip's own
    /// transition first and stops — and it is right for sound: both fades
    /// are audible, where two dissolves on one layer would be two opacity
    /// ramps the compositor has only one slot for.
    pub(crate) fn crossfade_gain(&self, stage: &Stage<'_>, t: Ticks, side: Side) -> f64 {
        let clips = stage
            .container
            .map(|nest| &nest.clips[..])
            .unwrap_or(&self.clips);
        let local = t
            .saturating_sub(stage.origin)
            .saturating_add(stage.clip.start);
        let Some((transition, progress, is_incoming)) =
            transition::crossfade_among(clips, stage.clip.id, local, side)
        else {
            return 1.0;
        };
        if !transition.audio {
            return 1.0;
        }
        let p = progress.clamp(0.0, 1.0);
        match (transition.audio_shape, is_incoming) {
            // R5-2's law on its own code path, so a transition with no
            // `audio_shape` plans exactly as before (spec §11 AU-115).
            (FadeShape::Plus3Db, true) => (p * FRAC_PI_2).sin(),
            (FadeShape::Plus3Db, false) => (p * FRAC_PI_2).cos(),
            (shape, true) => shape.gain(p),
            (shape, false) => shape.gain(1.0 - p),
        }
    }

    /// Every tick one stage's crossfade needs sampled at, in PROJECT time,
    /// or `None` when the stage is in no audio-true overlap.
    ///
    /// The two edges plus a grid across the span, at the step the action
    /// loop uses: `ACTION_SAMPLE` normally, widened so one span can never
    /// contribute more than `MAX_ACTION_SAMPLES` points. Both constants stay
    /// private to this module — the crossfade is sampled here, beside the
    /// actions, exactly so that nothing has to widen for it.
    pub(crate) fn crossfade_breaks(&self, stage: &Stage<'_>) -> Option<Vec<Ticks>> {
        let clips = stage
            .container
            .map(|nest| &nest.clips[..])
            .unwrap_or(&self.clips);
        let mut out: Vec<Ticks> = Vec::new();
        for overlap in [
            transition::overlap_before_of(clips, stage.clip.id),
            transition::overlap_after_of(clips, stage.clip.id),
        ]
        .into_iter()
        .flatten()
        {
            // Asked through `crossfade_among` rather than by reading the
            // later clip's `transition_in` here, so "what transition covers
            // this instant" has one spelling in the crate.
            let Some((transition, _, _)) =
                transition::crossfade_among(clips, stage.clip.id, overlap.start, Side::Right)
            else {
                continue;
            };
            if !transition.audio || overlap.duration <= 0 {
                continue;
            }
            // Container time back to project time: the inverse of
            // `crossfade_gain`'s `local`.
            let project = |c: Ticks| {
                c.saturating_sub(stage.clip.start)
                    .saturating_add(stage.origin)
            };
            let start = project(overlap.start);
            let end = project(overlap.start.saturating_add(overlap.duration));
            out.push(start);
            out.push(end);
            let step = ACTION_SAMPLE.max(overlap.duration / MAX_ACTION_SAMPLES + 1);
            let mut t = start.saturating_add(step);
            while t < end {
                out.push(t);
                t = t.saturating_add(step);
            }
        }
        if out.is_empty() {
            None
        } else {
            Some(out)
        }
    }
}
//! Fade and crossfade shapes (spec §11 AU-114, AU-115): the gain a
//! [`FadeShape`] gives at a progress, and the ticks a shaped fade has to be
//! sampled at for its curve to survive `audio.rs`'s coalescing.
//!
//! A shape is a curve over the fade's progress u in 0..1, read by
//! `audio.rs`'s fades (u is `t / fade_in` in, `remaining / fade_out` out) and
//! by `audio_crossfade.rs` over a transition's eased progress. `linear` is
//! `u` itself — the expression the fades always used, so a linear fade
//! plans exactly as before and needs no samples — and the other three are
//! not straight lines, so a fade in one of them is sampled on the action
//! grid, as an eased action is.
//!
//! It also holds [`Transition`]'s `Default`, because the one field that keeps
//! it from being derived is a shape: a transition's file default crossfades
//! (when `audio` is on) at R5-2's constant power, `plus_3db`, where a fade's
//! default is `linear`.

use std::f64::consts::{FRAC_PI_2, PI};

use crate::audio::{ACTION_SAMPLE, MAX_ACTION_SAMPLES};
use crate::model::{Curve, FadeShape, Transition, TransitionKind};
use crate::time::Ticks;

impl FadeShape {
    /// The gain at progress `u`, clamped to 0..1: Linear `u`, S-curve
    /// `(1 − cos πu)/2`, +3 dB `sin(uπ/2)`, −3 dB `1 − cos(uπ/2)`. Each runs
    /// from exactly 0 to exactly 1 at the two ends, so a fade never leaves a
    /// residue of gain where it should be silent or full.
    pub(crate) fn gain(self, u: f64) -> f64 {
        match self {
            FadeShape::Linear => u,
            _ if u <= 0.0 => 0.0,
            _ if u >= 1.0 => 1.0,
            FadeShape::SCurve => (1.0 - (PI * u).cos()) / 2.0,
            FadeShape::Plus3Db => (u * FRAC_PI_2).sin(),
            FadeShape::Minus3Db => 1.0 - (u * FRAC_PI_2).cos(),
        }
    }
}

/// The ticks a shaped fade over `[start, end]` (project time) is sampled at:
/// its two edges plus the action grid across it — `ACTION_SAMPLE`, widened
/// so one fade never contributes more than `MAX_ACTION_SAMPLES` points, the
/// step `audio.rs`'s action loop and `audio_crossfade.rs` both use.
pub(crate) fn fade_breaks(start: Ticks, end: Ticks) -> Vec<Ticks> {
    let mut out = vec![start, end];
    let span = end.saturating_sub(start);
    if span <= 0 {
        return out;
    }
    let step = ACTION_SAMPLE.max(span / MAX_ACTION_SAMPLES + 1);
    let mut t = start.saturating_add(step);
    while t < end {
        out.push(t);
        t = t.saturating_add(step);
    }
    out
}

impl Default for Transition {
    /// The FILE default (`model.rs`'s doc on [`Transition`]): a cross
    /// dissolve, linear, silent — and, should `audio` be switched on, R5-2's
    /// constant-power crossfade, `plus_3db` (spec §11 AU-115).
    fn default() -> Self {
        Transition {
            kind: TransitionKind::CrossDissolve,
            curve: Curve::Linear,
            audio: false,
            audio_shape: FadeShape::Plus3Db,
        }
    }
}
//! `set_transition_style` — a transition's curve and whether it crossfades
//! the sound, leaving its kind alone (spec §6, table "Transitions").
//!
//! Cut out of `edit_transition.rs` under the size rule, a pure move (road
//! map "audio" AP11's toll): the op only restyles a stored transition and
//! moves no clip, so it needs none of that module's placement arithmetic.

use crate::edit_adjustment::adjustment_transition;
use crate::model::{Curve, FadeShape, Project, Transition, TransitionKind};
use crate::outcome::Outcome;

impl Project {
    /// Sets the transition's CURVE and whether it crossfades the sound
    /// (spec §6, format version 7), and the crossfade's shape (format 29,
    /// spec §11 AU-115), leaving its kind alone.
    ///
    /// A second op rather than two more arguments on
    /// [`Project::set_transition`], and the reason is the envelope: that op
    /// reads an absent `kind` and an explicit `null` as the same thing — a
    /// CLEAR — so it has no way to spell "leave the curve where it is".
    /// Here no argument is nullable, so an absent key is unambiguous and
    /// means keep.
    ///
    /// It stores on the same terms `set_transition` does: any clip, with or
    /// without an overlap, since a stored transition on a clip with no
    /// overlap is simply undrawn until one exists. With NO stored
    /// transition and at least one key given it mints
    /// (`cross_dissolve`, spec §11 R5-2) and applies the style over it;
    /// with NO key given it is an identity whatever the clip holds
    /// and never mints — asking for no change is not a way to make a
    /// transition. `Err` for an unknown clip.
    pub fn set_transition_style(
        &self,
        clip: u32,
        curve: Option<Curve>,
        audio: Option<bool>,
        audio_shape: Option<FadeShape>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?;
        let stored = target.transition_in;
        if curve.is_none() && audio.is_none() && audio_shape.is_none() {
            return Ok(Outcome::Identity);
        }
        if let Some(why) = adjustment_transition(target) {
            return Ok(Outcome::Refused(why));
        }
        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(clip) {
            let mut transition =
                stored.unwrap_or_else(|| Transition::minted(TransitionKind::default()));
            if let Some(curve) = curve {
                transition.curve = curve;
            }
            if let Some(audio) = audio {
                transition.audio = audio;
            }
            if let Some(shape) = audio_shape {
                transition.audio_shape = shape;
            }
            slot.transition_in = Some(transition);
        }
        self.finish(next)
    }
}
