200	            return skip(job, "its processing could not be measured: no volume could be solved.")
201	        }
202	        guard let limiter = row.limiter else {
203	            readings.append(processed)
204	            solved[job.reading.clip] = AudioNormalize.Solved(
205	                volume: row.volume, limiter: nil, resultLUFS: row.resultLUFS,
206	                resultTruePeakDBTP: row.resultTruePeakDBTP, limit: row.limit, renders: 1)
207	            return advance()
208	        }
209	        verify(job, processed, chain: chain, volume: row.volume, limiter: limiter, verifies: 0)
210	    }
211	
212	    /// One verify render of the chain with `{volume, limiter}` (the stage
213	    /// told the volume, AU-22), read through the fader at that volume, so R
214	    /// is its loudness as it stands; again, nearer, while it misses the
215	    /// target by more than the tolerance, the volume can still move toward it
216	    /// (not at the ceiling and short) and fewer than `maximumVerifyRenders`
217	    /// have run.
218	    private func verify(
219	        _ job: Job, _ processed: AudioNormalize.LoudnessReading, chain: AudioPatch,
220	        volume: Double, limiter: LimiterProps, verifies: Int
221	    ) {
222	        guard !cancelled.isSet else { return answer(nil) }
223	        var patch = chain
224	        patch.volume = volume
225	        patch.limiter = .some(limiter)
226	        guard let trial = trial(job.reading.clip, patch) else {
227	            return skip(job, "its processing could not be measured: its settings were refused.")
228	        }
229	        render(trial, job.reading.clip) { [weak self] rendered in
230	            guard let self else { return }
231	            // Read through the clip's fader at `volume` (`ProcessedLoudness.render`).
232	            guard case .steps(let steps, let peaks) = rendered,
233	                let result = StepLoudness.integrated(steps)
234	            else { return self.settle(job, rendered) }
235	            let peak = peaks.max() ?? 0
236	            let count = verifies + 1
237	            let target = self.targetLUFS
238	            let capped = volume >= AudioNormalize.maxGain && result < target
239	            if abs(result - target) > Self.verifyToleranceLU, !capped,
240	                count < Self.maximumVerifyRenders
241	            {
242	                let nearer = min(volume * pow(10, (target - result) / 20), AudioNormalize.maxGain)
243	                return self.verify(
244	                    job, processed, chain: chain, volume: nearer, limiter: limiter,
245	                    verifies: count)
246	            }
247	            self.readings.append(processed)
248	            self.solved[job.reading.clip] = AudioNormalize.Solved(
249	                volume: volume, limiter: limiter, resultLUFS: result,
250	                resultTruePeakDBTP: peak > 0 ? 20 * log10(peak) : -.infinity,
251	                limit: volume >= AudioNormalize.maxGain
252	                    && result < target - Self.verifyToleranceLU ? .maxGain : nil,
253	                renders: 1 + count)
254	            self.advance()
255	        }
256	    }
