292	    /// AU-64 (b): the press's project with one `set_audio` of `patch` on
293	    /// `clip`, scoped to the nest it read in; nil when the core refuses it.
294	    /// Match Audio's target trials are made here too (AU-124).
295	    static func trial(base: ReelProject, scope: UInt32?, clip: UInt32, patch: AudioPatch)
296	        -> ReelProject?
297	    {
298	        let op = ReelOp.setAudio(clips: [clip], patch: patch).scoped(scope)
299	        let handle: ReelProject
300	        switch try? base.applying(op) {
301	        case .applied(let updated)?: handle = updated
302	        case .identity?: handle = base
303	        default: return nil
304	        }
305	        guard let scope else { return handle }
306	        return handle.scoped(scope)
307	    }
