309	    /// `ProcessedLoudness.render` on its queue; `then` on main with the
310	    /// answer, the key kept for `finish` (released at once when the run has
311	    /// already finished).
312	    private func render(
313	        _ trial: ReelProject, _ clip: UInt32,
314	        then: @escaping (ProcessedLoudness.Rendered) -> Void
315	    ) {
316	        let urls = self.urls
317	        let resolution = self.resolution
318	        let flag = cancelled
319	        ProcessedLoudness.queue.async { [weak self] in
320	            let (rendered, key) = ProcessedLoudness.render(
321	                trial, clip: clip, urls: urls, resolution: resolution,
322	                cancelled: { flag.isSet })
323	            DispatchQueue.main.async {
324	                guard let self, !self.finished else {
325	                    RampAudioRenders.shared.release(owner: key)
326	                    return
327	                }
328	                self.keys.append(key)
329	                then(rendered)
330	            }
331	        }
332	    }
